//Current HKT Time
var currHKT =new GlideDateTime();
currHKT.setTimeZone('Hongkong');//["US/Eastern" , "US/Eastern" , "PST" ]
gs.info('HONGK KONG TIME ' + currHKT.getDisplayValue()); //Current HKT Time
////Current HKT Time
gs.info("////////////");
//gs.info("////////////");
//gs.info("////////////");

//5Pm HKT reference Time
var hktDateTime = new GlideDateTime(currHKT.getDisplayValue());
var hktDate = hktDateTime.getDate(); //HKT time
var hktfivePmRef = new GlideDateTime();
hktfivePmRef.setValue(hktDate + " " + "20:00:00"); //5Pm HKT current Day 
gs.info("5pm HKT " + hktfivePmRef);
//5Pm HKT reference Time

//Received Record UTC Time
var recTime = new GlideDateTime(); //record time
recTime.setValue("2024-07-16 18:00:00"); // pass the updated time
gs.info( "Record Time " +  recTime);
//Received Record UTC Time

var balTime = gs.dateDiff(recTime,hktfivePmRef); //past,current time difference
gs.info("balTime " + balTime);

var dur = new GlideDuration('0' + " " + balTime);
gs.info("Balnce Duration to reach 5PM HKT " + dur.getDisplayValue());


